/**
 * Bubble Sort Algorithm Implementation
 * 
 * Bubble Sort is a simple comparison-based sorting algorithm that repeatedly
 * steps through the list, compares adjacent elements, and swaps them if they
 * are in the wrong order. The pass through the list is repeated until the
 * list is sorted.
 * 
 * Algorithm Logic:
 * 1. Start from the first element, compare it with the next element
 * 2. If the current element is greater than the next, swap them
 * 3. Move to the next pair and repeat until the end of the array
 * 4. After each complete pass, the largest unsorted element "bubbles up" to its correct position
 * 5. Repeat the process for the remaining unsorted portion
 * 6. Continue until no swaps are needed (array is sorted)
 * 
 * Time Complexity:
 * - Best Case: O(n) - when array is already sorted (with optimization flag)
 * - Average Case: O(n²) - typical random array
 * - Worst Case: O(n²) - when array is reverse sorted
 * 
 * Space Complexity: O(1) - only uses a constant amount of extra space
 * 
 * Stability: Stable - maintains relative order of equal elements
 */

// Constants for validation
const MAX_ARRAY_LENGTH = 100;
const MIN_VALUE = -10000;
const MAX_VALUE = 10000;

/**
 * Custom error class for Bubble Sort validation errors
 */
class BubbleSortError extends Error {
    constructor(message) {
        super(message);
        this.name = 'BubbleSortError';
    }
}

/**
 * Validates the input array before sorting
 * @param {Array} arr - The array to validate
 * @throws {BubbleSortError} If validation fails
 */
function validateInput(arr) {
    // Check if input is an array
    if (!Array.isArray(arr)) {
        throw new BubbleSortError('Input must be an array');
    }

    // Check if array is empty
    if (arr.length === 0) {
        throw new BubbleSortError('Array cannot be empty');
    }

    // Check array length constraint
    if (arr.length > MAX_ARRAY_LENGTH) {
        throw new BubbleSortError(
            `Array length exceeds maximum limit of ${MAX_ARRAY_LENGTH} elements. ` +
            `Received: ${arr.length} elements`
        );
    }

    // Validate each element in the array
    for (let i = 0; i < arr.length; i++) {
        const element = arr[i];

        // Check if element is a number
        if (typeof element !== 'number') {
            throw new BubbleSortError(
                `All elements must be integers. ` +
                `Invalid element at index ${i}: "${element}" (type: ${typeof element})`
            );
        }

        // Check if element is an integer (not NaN, not Infinity)
        if (!Number.isInteger(element)) {
            throw new BubbleSortError(
                `All elements must be integers. ` +
                `Invalid element at index ${i}: ${element}`
            );
        }

        // Check value range constraint
        if (element < MIN_VALUE || element > MAX_VALUE) {
            throw new BubbleSortError(
                `All elements must be between ${MIN_VALUE} and ${MAX_VALUE}. ` +
                `Invalid element at index ${i}: ${element}`
            );
        }
    }
}

/**
 * Swaps two elements in an array
 * @param {Array} arr - The array containing elements to swap
 * @param {number} i - Index of first element
 * @param {number} j - Index of second element
 */
function swap(arr, i, j) {
    // Using destructuring assignment for cleaner swap
    [arr[i], arr[j]] = [arr[j], arr[i]];
}

/**
 * Sorts an array of integers using the Bubble Sort algorithm
 * @param {number[]} arr - Array of integers to sort
 * @param {boolean} [ascending=true] - Sort in ascending order if true, descending if false
 * @returns {Object} Object containing sorted array and statistics
 * @throws {BubbleSortError} If input validation fails
 */
function bubbleSort(arr, ascending = true) {
    // Validate input before processing
    validateInput(arr);

    // Create a copy of the array to avoid mutating the original
    const sortedArray = [...arr];
    const n = sortedArray.length;

    // Statistics tracking
    let comparisons = 0;
    let swaps = 0;
    let passes = 0;

    /**
     * Outer loop: Controls the number of passes
     * After each pass, the largest (or smallest) element moves to its final position
     * We need at most (n-1) passes to sort the array
     */
    for (let i = 0; i < n - 1; i++) {
        // Optimization flag: track if any swaps occurred in this pass
        // If no swaps occur, the array is already sorted
        let swapped = false;
        passes++;

        /**
         * Inner loop: Compares adjacent elements
         * (n - 1 - i) because after each pass, the last i elements are already sorted
         * This optimization reduces unnecessary comparisons
         */
        for (let j = 0; j < n - 1 - i; j++) {
            comparisons++;

            // Compare adjacent elements based on sort order
            const shouldSwap = ascending 
                ? sortedArray[j] > sortedArray[j + 1]
                : sortedArray[j] < sortedArray[j + 1];

            if (shouldSwap) {
                // Swap elements if they are in wrong order
                swap(sortedArray, j, j + 1);
                swaps++;
                swapped = true;
            }
        }

        /**
         * Early termination optimization:
         * If no swaps occurred in a pass, the array is already sorted
         * This improves best-case complexity to O(n)
         */
        if (!swapped) {
            break;
        }
    }

    // Return sorted array along with performance statistics
    return {
        sortedArray,
        statistics: {
            originalLength: n,
            passes,
            comparisons,
            swaps,
            sortOrder: ascending ? 'ascending' : 'descending'
        }
    };
}

/**
 * Simple wrapper function that only returns the sorted array
 * @param {number[]} arr - Array of integers to sort
 * @returns {number[]} Sorted array
 */
